'use strict';
/* Saved settings only. Every outgoing action remains in the existing reviewed job/reply flow. */
window.OperationCampaigns=(()=>{
 const base='/api/scanner/operations',h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const mediaId=v=>typeof v==='string'&&/^[a-f0-9]{32}$/.test(v),identity=a=>a&&typeof a.id==='string'&&Number.isSafeInteger(a.telegram_id)&&a.telegram_id>0?a.id+':'+a.telegram_id:'';
 const profiles={loaded:false,busy:false,items:[],selected:'',editor:null,error:'',note:''},templates=new Map();let context={accounts:[]};
 const freshProfile=()=>({name:'',description:'',text:'',media:[],delay_seconds:60,daily_limit:20,keywords:[],stop_words:[],contact:''});
 const currentAccount=(id,tid)=>context.accounts.find(a=>a.id===id&&a.telegram_id===tid),words=v=>String(v||'').split(/[\n,]+/).map(s=>s.trim()).filter(Boolean),safeMedia=v=>Array.isArray(v)&&v.length<=10&&v.every(mediaId);
 async function api(path,body){const response=await fetch(base+path,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json','X-Scanner-Request':'1'},signal:AbortSignal.timeout(60000),...(body===undefined?{}:{body:JSON.stringify(body)})});let result;try{result=await response.json();}catch{throw Error('Сервер не подтвердил сохранение. Проверьте список перед повтором.');}if(!response.ok)throw Error(typeof result.detail==='string'?result.detail:'Не удалось сохранить настройки.');return result;}
 function profileValid(p){return p&&Number.isSafeInteger(p.id)&&p.id>0&&Number.isSafeInteger(p.revision)&&p.revision>0&&typeof p.name==='string'&&typeof p.text==='string'&&typeof p.description==='string'&&typeof p.contact==='string'&&safeMedia(p.media)&&Number.isFinite(p.delay_seconds)&&Number.isFinite(p.daily_limit)&&Array.isArray(p.keywords)&&p.keywords.every(v=>typeof v==='string')&&Array.isArray(p.stop_words)&&p.stop_words.every(v=>typeof v==='string');}
 function templateValid(t){return t&&Number.isSafeInteger(t.id)&&t.id>0&&Number.isSafeInteger(t.revision)&&t.revision>0&&typeof t.name==='string'&&typeof t.text==='string';}
 function copy(v){return JSON.parse(JSON.stringify(v));}
 const status=(error,note)=>`<p role="status" aria-live="polite" class="${error?'ls-error':'small'}">${h(error||note)}</p>`;
 function profileEditor(){const p=profiles.editor;if(!p)return '';return `<form data-campaign-editor><fieldset style="border:0;padding:0;min-width:0"${profiles.busy?' disabled':''}><h4>${p.id?'Редактирование профиля · версия '+p.revision:'Новый профиль'}</h4><label class="ls-field">Название профиля<input name="name" maxlength="100" required value="${h(p.name)}"></label><label class="ls-field">Заметка для команды<textarea name="description" maxlength="1000" rows="2">${h(p.description)}</textarea></label><label class="ls-field">Текст публикации<textarea name="text" maxlength="4096" rows="5">${h(p.text)}</textarea></label><div class="ls-grid"><label class="ls-field">Пауза между действиями, секунд<input type="number" name="delay_seconds" min="30" max="3600" required value="${h(p.delay_seconds)}"></label><label class="ls-field">Дневной предел<input type="number" name="daily_limit" min="1" max="100" required value="${h(p.daily_limit)}"></label></div><label class="ls-field">Ключевые слова, по одному на строку<textarea name="keywords" maxlength="6000" rows="2">${h(p.keywords.join('\n'))}</textarea></label><label class="ls-field">Стоп-слова, по одному на строку<textarea name="stop_words" maxlength="6000" rows="2">${h(p.stop_words.join('\n'))}</textarea></label><p class="small">Ключевые слова и стоп-слова отмечают входящие ответы на публикацию в журнале. Они не изменяют выбранные группы и не запускают ответы.</p><label class="ls-field">Контакт для обращения<input name="contact" maxlength="160" value="${h(p.contact)}"></label><p class="small">Контакт хранится отдельно. В публикацию попадает только текст из черновика.</p><p class="small">Фото профиля: ${p.media.length}.</p><div style="display:flex;gap:6px;flex-wrap:wrap">${p.media.map((id,i)=>`<span><img src="${base}/media/${id}" alt="Фото профиля ${i+1}" width="80"><button type="button" class="button secondary" data-campaign-action="profile-remove-media" data-index="${i}"${profiles.busy?' disabled':''}>Убрать фото ${i+1}</button></span>`).join('')}</div><div class="ls-actions"><button type="button" class="button secondary" data-campaign-action="profile-copy-draft"${profiles.busy?' disabled':''}>Скопировать текст, фото и паузы из черновика</button><button type="submit" class="button"${profiles.busy?' disabled':''}>${profiles.busy?'Сохраняем…':p.id?'Сохранить новую версию профиля':'Сохранить новый профиль'}</button>${p.id?`<button type="button" class="button secondary" data-campaign-action="profile-archive"${profiles.busy?' disabled':''}>${p.archived?'Вернуть профиль из архива':'Архивировать профиль'}</button>`:''}</div></fieldset></form>`;}
 function profileContent(){return `<h3>Профили кампаний</h3><p class="small">Сохраните текст, фото и настройки для следующей публикации. Подстановка изменяет только черновик; отправитель, группы и подтверждения остаются выбранными вами.</p><div class="ls-actions"><button type="button" class="button secondary" data-campaign-action="profiles-load"${profiles.busy?' disabled':''}>${profiles.loaded?'Обновить список профилей':'Загрузить профили'}</button><button type="button" class="button secondary" data-campaign-action="profile-new"${profiles.busy?' disabled':''}>Новый профиль</button></div>${status(profiles.error,profiles.note)}${profiles.loaded?`<label class="ls-field">Сохранённый профиль<select data-campaign-select><option value="">Выберите профиль</option>${profiles.items.map(p=>`<option value="${h(p.id)}"${String(profiles.selected)===String(p.id)?' selected':''}>${h(p.name)} · v${p.revision}${p.archived?' · архив':''}</option>`).join('')}</select></label><div class="ls-actions"><button type="button" class="button secondary" data-campaign-action="profile-open"${profiles.busy?' disabled':''}>Открыть выбранную версию</button><button type="button" class="button secondary" data-campaign-action="profile-apply"${profiles.busy?' disabled':''}>Подставить сохранённый профиль в черновик</button><button type="button" class="button secondary" data-campaign-action="profile-contact"${profiles.busy?' disabled':''}>Добавить контакт профиля в текст черновика</button></div>`:''}${profileEditor()}`;}
 function composeView(){return '<details class="panel ls-section" data-operation-campaigns style="min-width:0;overflow-wrap:anywhere"><summary>Профили кампаний и сохранённые настройки</summary><div data-campaign-profile-content></div></details>';}
 function templateState(a){const key=identity(a);let s=templates.get(key);if(!s){s={identity:key,account:a.id,telegram_id:a.telegram_id,loaded:false,busy:false,items:[],editor:{name:'',text:''},error:'',note:''};templates.set(key,s);}return s;}
 function templateContent(a,s){const p=s.editor;return `<h4>Шаблоны ручных ответов</h4><p class="small">Привязаны к этому Telegram-аккаунту, ID ${h(a.telegram_id)}. Шаблон подставляет текст в форму ответа; отправку вы подтверждаете отдельно.</p><div class="ls-actions"><button type="button" class="button secondary" data-campaign-action="templates-load"${s.busy?' disabled':''}>${s.loaded?'Обновить шаблоны ответов':'Загрузить шаблоны ответов'}</button><button type="button" class="button secondary" data-campaign-action="template-new"${s.busy?' disabled':''}>Новый шаблон ответа</button></div>${status(s.error,s.note)}${s.loaded?`<label class="ls-field">Сохранённый шаблон<select data-campaign-template-select><option value="">Выберите шаблон</option>${s.items.map(t=>`<option value="${h(t.id)}"${p.id===t.id?' selected':''}>${h(t.name)} · v${t.revision}${t.archived?' · архив':''}</option>`).join('')}</select></label><button type="button" class="button secondary" data-campaign-action="template-open"${s.busy?' disabled':''}>Открыть шаблон</button>`:''}<form data-campaign-template-editor><fieldset style="border:0;padding:0;min-width:0"${s.busy?' disabled':''}><label class="ls-field">Название шаблона<input name="name" maxlength="100" required value="${h(p.name)}"></label><label class="ls-field">Текст ручного ответа<textarea name="text" maxlength="4096" rows="3" required>${h(p.text)}</textarea></label><div class="ls-actions"><button type="submit" class="button secondary"${s.busy?' disabled':''}>${p.id?'Сохранить версию шаблона':'Сохранить шаблон ответа'}</button>${p.id?`<button type="button" class="button secondary" data-campaign-action="template-archive"${s.busy?' disabled':''}>${p.archived?'Вернуть шаблон из архива':'Архивировать шаблон'}</button>`:''}</div></fieldset></form>`;}
 function accountView(a){if(!identity(a))return '';return `<details data-operation-campaigns data-campaign-account="${h(a.id)}" data-telegram-id="${a.telegram_id}" style="min-width:0;overflow-wrap:anywhere"><summary>Шаблоны ответов этого аккаунта</summary><div data-campaign-template-content></div></details>`;}
 function replyPicker(a,locked=false){if(!identity(a))return '';const s=templateState(a);return `<div data-campaign-reply-picker data-campaign-account="${h(a.id)}" data-telegram-id="${a.telegram_id}" data-locked="${locked?'1':'0'}" style="min-width:0">${pickerContent(a,s,locked)}</div>`;}
 function pickerContent(a,s,locked){return `<label class="ls-field">Шаблон ответа этого аккаунта<select data-tracking-template-choice${locked||!s.loaded||s.busy?' disabled':''}><option value="">Выберите шаблон</option>${s.items.filter(t=>!t.archived).map(t=>`<option value="${h(t.id)}">${h(t.name)} · v${t.revision}</option>`).join('')}</select></label><div class="ls-actions"><button type="button" class="button secondary" data-campaign-action="reply-templates-load"${locked||s.busy?' disabled':''}>${s.loaded?'Обновить список шаблонов':'Загрузить шаблоны для ответа'}</button><button type="button" class="button secondary" data-tracking-action="template-apply"${locked||!s.loaded||s.busy?' disabled':''}>Подставить шаблон в ответ</button></div>${s.loaded&&!s.items.some(t=>!t.archived)?'<p class="small">У этого аккаунта ещё нет доступных шаблонов. Создайте шаблон в его настройках.</p>':''}${status(s.error,'')}`;}
 function renderProfiles(){for(const el of document.querySelectorAll('[data-campaign-profile-content]'))el.innerHTML=profileContent();}
 function renderTemplates(a){const s=templateState(a);for(const el of document.querySelectorAll('[data-campaign-account][data-telegram-id]'))if(el.dataset.campaignAccount===a.id&&Number(el.dataset.telegramId)===a.telegram_id){const content=el.querySelector('[data-campaign-template-content]');if(content)content.innerHTML=templateContent(a,s);if(el.hasAttribute('data-campaign-reply-picker'))el.innerHTML=pickerContent(a,s,el.dataset.locked==='1');}}
 function mount(next){context=next||{accounts:[]};context.accounts=Array.isArray(context.accounts)?context.accounts:[];for(const [key,s]of templates)if(!currentAccount(s.account,s.telegram_id))templates.delete(key);renderProfiles();for(const a of context.accounts)if(identity(a))renderTemplates(a);}
 function readProfile(f){const p=profiles.editor;if(!p)return;for(const k of ['name','description','text','contact'])p[k]=f.elements[k].value;for(const k of ['delay_seconds','daily_limit'])p[k]=Number(f.elements[k].value);p.keywords=words(f.elements.keywords.value);p.stop_words=words(f.elements.stop_words.value);}
 function accountFrom(el){const n=el.closest('[data-campaign-account][data-telegram-id]');return n?currentAccount(n.dataset.campaignAccount,Number(n.dataset.telegramId)):null;}
 function readTemplate(f){const a=accountFrom(f);if(!a)return;const s=templateState(a);s.editor.name=f.elements.name.value;s.editor.text=f.elements.text.value;}
 async function loadProfiles(){if(profiles.busy)return;profiles.busy=true;profiles.error='';renderProfiles();try{const d=await api('/campaigns?include_archived=true');if(!Array.isArray(d.campaigns)||!d.campaigns.every(profileValid))throw Error('Сервер вернул неполные профили. Черновик редактора сохранён.');profiles.items=d.campaigns;profiles.loaded=true;profiles.note='Список обновлён. Несохранённые правки редактора сохранены; открытие версии заменит их.';}catch(e){profiles.error=e.message;}finally{profiles.busy=false;renderProfiles();}}
 async function saveProfile(archive=false){if(profiles.busy||!profiles.editor)return;const payload=copy(profiles.editor);profiles.busy=true;profiles.error='';renderProfiles();try{const result=archive?await api('/campaigns/'+encodeURIComponent(payload.id)+'/archive',{revision:payload.revision,archived:!payload.archived}):await api('/campaigns',{...(payload.id?{id:payload.id,revision:payload.revision}:{}),...Object.fromEntries(['name','description','text','media','delay_seconds','daily_limit','keywords','stop_words','contact'].map(k=>[k,payload[k]]))});if(!profileValid(result.campaign))throw Error('Версия профиля не подтверждена сервером. Проверьте список перед повтором.');profiles.items=profiles.items.filter(p=>p.id!==result.campaign.id).concat([result.campaign]);profiles.loaded=true;profiles.editor=copy(result.campaign);profiles.selected=String(result.campaign.id);profiles.note='Профиль сохранён. Для изменения публикации подставьте сохранённую версию в черновик.';}catch(e){profiles.error=e.message+' Ваши правки оставлены в редакторе.';}finally{profiles.busy=false;renderProfiles();}}
 async function loadTemplates(a){const s=templateState(a);if(s.busy)return;s.busy=true;s.error='';renderTemplates(a);try{const d=await api('/accounts/'+encodeURIComponent(a.id)+'/reply-templates?include_archived=true');if(!currentAccount(a.id,a.telegram_id)||templates.get(identity(a))!==s)return;if(d.account!==a.id||d.telegram_id!==a.telegram_id||!Array.isArray(d.templates)||!d.templates.every(templateValid))throw Error('Шаблоны относятся к другому аккаунту или неполны.');s.items=d.templates;s.loaded=true;s.note='Список шаблонов обновлён. Несохранённый текст редактора сохранён.';}catch(e){s.error=e.message;}finally{s.busy=false;if(currentAccount(a.id,a.telegram_id)&&templates.get(identity(a))===s)renderTemplates(a);}}
 async function saveTemplate(a,archive=false){const s=templateState(a);if(s.busy)return;const payload=copy(s.editor);s.busy=true;s.error='';renderTemplates(a);try{const path='/accounts/'+encodeURIComponent(a.id)+'/reply-templates'+(archive?'/'+encodeURIComponent(payload.id)+'/archive':'');const result=await api(path,archive?{telegram_id:a.telegram_id,revision:payload.revision,archived:!payload.archived}:{telegram_id:a.telegram_id,...(payload.id?{id:payload.id,revision:payload.revision}:{}),name:payload.name,text:payload.text});if(!currentAccount(a.id,a.telegram_id)||templates.get(identity(a))!==s)return;if(result.account!==a.id||result.telegram_id!==a.telegram_id||!templateValid(result.template))throw Error('Личность или версия шаблона не подтверждены. Проверьте список.');s.items=s.items.filter(t=>t.id!==result.template.id).concat([result.template]);s.loaded=true;s.editor=copy(result.template);s.note='Шаблон сохранён для этого аккаунта. Он не отправляется автоматически.';}catch(e){s.error=e.message+' Ваши правки оставлены в редакторе.';}finally{s.busy=false;if(currentAccount(a.id,a.telegram_id)&&templates.get(identity(a))===s)renderTemplates(a);}}
 function selectedProfile(b){const id=b.closest('[data-operation-campaigns]')?.querySelector('[data-campaign-select]')?.value;return profiles.items.find(p=>p.id===Number(id));}
 function composeReference(f){if(f?.elements.kind?.value!=='post')return {};const id=Number(f?.elements.campaign_id?.value),revision=Number(f?.elements.campaign_revision?.value);return Number.isSafeInteger(id)&&id>0&&Number.isSafeInteger(revision)&&revision>0?{campaign_id:id,campaign_revision:revision}:{};}
 function resolveTemplate(a,id){if(!identity(a)||!currentAccount(a.id,a.telegram_id))return null;const t=templates.get(identity(a))?.items.find(t=>t.id===Number(id)&&!t.archived);return t?copy(t):null;}
 function jobView(j){const p=j.spec?.campaign_snapshot;if(!p||typeof p!=='object')return '';return `<details style="min-width:0;overflow-wrap:anywhere"><summary>Профиль кампании: ${h(p.name||j.spec.campaign_id||'сохранённый')} · v${h(p.revision||j.spec.campaign_revision)}</summary><p class="small">Снимок профиля на момент сохранения задания. Фактический текст и фото задания показаны выше; последующие изменения профиля не меняют это задание.</p>${p.description?`<p>${h(p.description)}</p>`:''}<p class="small">Текст исходного профиля:</p><p style="white-space:pre-wrap">${h(p.text||'')}</p>${safeMedia(p.media)?p.media.map((id,i)=>`<img src="${base}/media/${id}" alt="Фото исходного профиля ${i+1}" width="80">`).join(''):''}<p class="small">Пауза исходного профиля: ${h(p.delay_seconds??'—')} сек. · Дневной предел: ${h(p.daily_limit??'—')}.</p>${p.contact?`<p>Контакт профиля: ${h(p.contact)}. Он не добавляется в текст автоматически.</p>`:''}<p class="small">Ключевые слова: ${h(Array.isArray(p.keywords)?p.keywords.join(', '):'—')||'—'}. Стоп-слова: ${h(Array.isArray(p.stop_words)?p.stop_words.join(', '):'—')||'—'}.</p></details>`;}
 document.addEventListener('input',e=>{const pf=e.target.closest('[data-campaign-editor]'),tf=e.target.closest('[data-campaign-template-editor]');if(pf)readProfile(pf);if(tf)readTemplate(tf);});
 document.addEventListener('change',e=>{if(e.target.matches('[data-campaign-select]'))profiles.selected=e.target.value;const pf=e.target.closest('[data-campaign-editor]'),tf=e.target.closest('[data-campaign-template-editor]');if(pf)readProfile(pf);if(tf)readTemplate(tf);});
 document.addEventListener('click',e=>{const b=e.target.closest('[data-campaign-action]');if(!b||b.disabled)return;const action=b.dataset.campaignAction,a=accountFrom(b);if(action==='profiles-load'){void loadProfiles();return;}if(action==='profile-new'){if(profiles.busy)return;profiles.editor=freshProfile();profiles.selected='';profiles.error='';profiles.note='Новый профиль. Группы и аккаунт в него не сохраняются.';renderProfiles();return;}if(action==='profile-copy-draft'){const d=context.getDraft?.();if(!profiles.editor||!d||d.kind!=='post'){profiles.error='Откройте черновик публикации в группы.';}else if(!safeMedia(d.media)){profiles.error='Не удалось проверить фото черновика.';}else{Object.assign(profiles.editor,{text:d.text||'',media:[...d.media],delay_seconds:d.delay_seconds,daily_limit:d.daily_limit});profiles.error='';profiles.note='Текст, фото и паузы скопированы в редактор профиля. Сохраните профиль отдельно.';}renderProfiles();return;}if(action==='profile-remove-media'){if(profiles.editor&&!profiles.busy)profiles.editor.media.splice(Number(b.dataset.index),1);renderProfiles();return;}if(action==='profile-archive'){void saveProfile(true);return;}if(action.startsWith('profile-')){const p=selectedProfile(b);if(!p){profiles.error='Выберите сохранённый профиль.';renderProfiles();return;}if(action==='profile-open'){profiles.editor=copy(p);profiles.error='';profiles.note='Открыта сохранённая версия '+p.revision+'.';renderProfiles();return;}if(p.archived){profiles.error='Сначала верните профиль из архива.';renderProfiles();return;}if(context.getDraft?.()?.kind!=='post'){profiles.error='Профиль можно подставить только в публикацию по группам.';renderProfiles();return;}try{if(action==='profile-apply'){if(!context.applyDraft)throw Error('Черновик недоступен.');context.applyDraft(copy(p));profiles.note='Версия '+p.revision+' подставлена в черновик. Проверьте фактический текст, фото и получателей.';}if(action==='profile-contact'){if(!p.contact.trim())throw Error('В профиле не указан контакт.');if(!context.appendContact)throw Error('Черновик недоступен.');context.appendContact(p.contact);profiles.note='Контакт добавлен в текст черновика. Проверьте его в предпросмотре.';}profiles.error='';}catch(err){profiles.error=err.message;}renderProfiles();return;}if(!a)return;const s=templateState(a);if(['templates-load','reply-templates-load'].includes(action)){void loadTemplates(a);return;}if(s.busy)return;if(action==='template-new'){s.editor={name:'',text:''};s.error='';s.note='Новый шаблон для ID '+a.telegram_id;renderTemplates(a);}if(action==='template-open'){const id=b.closest('[data-campaign-account]')?.querySelector('[data-campaign-template-select]')?.value,t=s.items.find(t=>t.id===Number(id));if(t){s.editor=copy(t);s.error='';s.note='Открыта версия '+t.revision;}else s.error='Выберите шаблон этого аккаунта.';renderTemplates(a);}if(action==='template-archive')void saveTemplate(a,true);});
 document.addEventListener('submit',e=>{const f=e.target;if(f.matches('[data-campaign-editor]')){e.preventDefault();e.stopImmediatePropagation();readProfile(f);void saveProfile();}if(f.matches('[data-campaign-template-editor]')){e.preventDefault();e.stopImmediatePropagation();readTemplate(f);const a=accountFrom(f);if(a)void saveTemplate(a);}},true);
 return {composeView,accountView,jobView,mount,composeReference,replyPicker,resolveTemplate};
})();
